insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lv', '/flags/history/lv-1562.svg', '1562-11-28', '1795-03-28', 'Duché de Courlande', 'Duchy of Courland', 'Duché vassal de la Pologne-Lituanie, la Courlande eut même des colonies, à Tobago et en Gambie, au XVIIe siècle.', 'A vassal duchy of Poland-Lithuania, Courland even had colonies, in Tobago and the Gambia, in the 17th century.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lv', 'https://flagcdn.com/lv.svg', '1918-11-18', '1940-08-05', 'République de Lettonie (1918-1940)', 'Republic of Latvia (1918–1940)', 'Le carmin-blanc-carmin, déjà décrit dans une chronique rimée du XIIIe siècle, devient le drapeau de la Lettonie indépendante, officialisé en 1921.', 'Carmine-white-carmine, already described in a 13th-century rhymed chronicle, became independent Latvia''s flag, made official in 1921.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lv', '/flags/history/lv-1953.svg', '1953-01-01', '1990-02-27', 'RSS de Lettonie (1953-1990)', 'Latvian SSR (1953–1990)', 'En 1953, le drapeau rouge reçoit des vagues bleues et blanches évoquant la mer Baltique ; le carmin-blanc-carmin revient le 27 février 1990.', 'In 1953 the red flag gained blue and white waves evoking the Baltic Sea; carmine-white-carmine returned on 27 February 1990.');
